{
  "version": 1,
  "cases": [
    {
      "id": "external-command",
      "route": "owner-command",
      "command": "bun",
      "args": [
        "./📜️script.ts",
        "test"
      ],
      "expected": [
        "owned",
        "prepare:2",
        "cargo:2"
      ],
      "consume": true
    },
    {
      "id": "repository-consumer",
      "route": "repository-test-body",
      "command": "bun",
      "args": [
        "./📜️script.ts",
        "test",
        "long",
        "--lib"
      ],
      "expected": [
        "refused"
      ],
      "consume": false
    },
    {
      "id": "unknown-command-refused",
      "route": "repository-test-body",
      "command": "node",
      "args": [
        "--eval",
        "1"
      ],
      "expected": [
        "refused"
      ],
      "consume": false
    },
    {
      "id": "custom-script-refused",
      "route": "repository-test-body",
      "command": "bun",
      "args": [
        "./foreign.ts",
        "test"
      ],
      "expected": [
        "refused"
      ],
      "consume": false
    },
    {
      "id": "other-command-refused",
      "route": "repository-test-body",
      "command": "bun",
      "args": [
        "./📜️script.ts",
        "build"
      ],
      "expected": [
        "refused"
      ],
      "consume": false
    },
    {
      "id": "current-owned-test-consumer",
      "route": "owner-command",
      "command": "bun",
      "args": [
        "./📜️script.ts",
        "test",
        "long",
        "--lib"
      ],
      "consume": true,
      "expected": [
        "owned",
        "prepare:2",
        "cargo:2"
      ]
    },
    {
      "id": "generic-process-body",
      "route": "owner-command",
      "command": "node",
      "args": [
        "--eval",
        "1"
      ],
      "consume": false,
      "expected": [
        "owned"
      ]
    },
    {
      "id": "arbitrary-owned-bun-body",
      "route": "owner-command",
      "command": "bun",
      "args": [
        "./foreign.ts",
        "build"
      ],
      "consume": false,
      "expected": [
        "owned"
      ]
    }
  ],
  "targets": [
    {
      "id": "external",
      "target": {
        "options": {
          "command": "bun ./📜️script.ts test"
        }
      },
      "expected": "owner-command"
    },
    {
      "id": "explicit-body",
      "target": {
        "options": {
          "command": "bun ./📜️script.ts test"
        }
      },
      "expected": "owner-command"
    },
    {
      "id": "level-sibling",
      "target": {
        "options": {
          "command": "bun \"./📜️script.ts\" test long"
        }
      },
      "expected": "owner-command"
    },
    {
      "id": "unknown-declaration",
      "target": {
        "options": {
          "command": "bun ./📜️script.ts test"
        }
      },
      "expected": "owner-command"
    },
    {
      "id": "build-body-refused",
      "target": {
        "options": {
          "command": "bun ./📜️script.ts build"
        }
      },
      "expected": "owner-command"
    }
  ],
  "testOwners": [
    "🧰️framework/🛍️products/💻️os/🔨️modules/🔌️plugin/📦️packages/🦀️rust",
    "✏️s/🔌️plugins/📐️cad/🗿️artifacts/📐️cad/📦️packages/🦀️rust",
    "✏️s/🔌️plugins/🏭️process/🗿️artifacts/🧊️process3d/📦️packages/🦀️rust",
    "✏️s/🔌️plugins/🌊️flow/🗿️artifacts/🌊️flow/📦️packages/🦀️rust",
    "✏️s/🔌️plugins/🪵️sourcing/🗿️artifacts/🗂️curation/📦️packages/🦀️rust"
  ],
  "callerTargets": [
    {
      "project": "🧰️framework/🛍️products/💻️os/🔨️modules/📺️renderer/🧑‍🎨engine/🎯️targets/🧊️wgpu/📦️packages/🟦️typescript/📋️project.json",
      "target": "check-wasm",
      "command": "bun ./📜️script.ts check-wasm",
      "dependencies": [
        "@semio-tech/ui-rs:generate",
        "@semio-tech/framework-schema:generate",
        "@semio-tech/ui-styling-tokens:generate",
        "@semio-tech/framework-graph:generate"
      ]
    },
    {
      "project": "🧰️framework/🛍️products/💻️os/🔨️modules/📺️renderer/🧑‍🎨engine/🎯️targets/🧊️wgpu/📦️packages/🟦️typescript/📋️project.json",
      "target": "wasm",
      "command": "bun ../../🏗️compiler/🌐️wasm/📜️script.ts build dev",
      "dependencies": [
        "workspace:deps-trunk",
        "workspace:deps-wasm-opt"
      ]
    },
    {
      "project": "🧰️framework/🛍️products/💻️os/🔨️modules/📺️renderer/🧑‍🎨engine/🎯️targets/🧊️wgpu/📦️packages/🟦️typescript/📋️project.json",
      "target": "wasm-release",
      "command": "bun ../../🏗️compiler/🌐️wasm/📜️script.ts build release",
      "dependencies": [
        "workspace:deps-trunk",
        "workspace:deps-wasm-opt"
      ]
    },
    {
      "project": "🧰️framework/🛍️products/🦑️repo/🔨️modules/📚️library/📦️packages/🟦️typescript/📋️project.json",
      "target": "test-runtime-fixture-graph",
      "command": "bun ./📜️script.ts test runtime-fixture-graph",
      "dependencies": [
        "workspace:deps-trunk",
        "workspace:deps-wasm-opt"
      ]
    }
  ]
}

